const platform = String($json.params?.platform || "").toLowerCase();
const channelKey = String($json.params?.channelKey || "");

let text = "";
let sender_id = "";
let quick_reply_payload = null;
let is_echo = false;

if (platform === "telegram") {
  text = $json.body?.message?.text || "";
  sender_id = String($json.body?.message?.chat?.id || "");
}

if (platform === "facebook") {
  const entry = $json.body?.entry?.[0];
  const fbMessage = entry?.messaging?.[0];

  const pageId = String(entry?.id || "");
  const senderId = String(fbMessage?.sender?.id || "");
  const recipientId = String(fbMessage?.recipient?.id || "");

  is_echo = fbMessage?.message?.is_echo === true;

  // أي رسالة طالعة من الصفحة / الموظف: تجاهلها
  if (is_echo || senderId === pageId || senderId === channelKey) {
    return [];
  }

  text = fbMessage?.message?.text || "";
  sender_id = senderId;
  quick_reply_payload = fbMessage?.message?.quick_reply?.payload || null;
}

return {
  platform,
  channelKey,
  text,
  sender_id,
  quick_reply_payload,
  is_echo,
  raw_body: $json.body || $json
};

const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;

const replies = $input.all().map(item => item.json);
//const text = String(base.text || "").toLowerCase().trim();
const text = String(base.quick_reply_payload || base.text || "").toLowerCase().trim();

const clients = integration.clients || integration.client || {};

const welcomeMessage =
  prep.welcome_message ||
  clients.welcome_message ||
  null;

// 1) Welcome message always has priority
if (prep.is_new_conversation === true && welcomeMessage) {
  return [
    {
      json: {
        platform: prep.platform,
        channelKey: prep.channelKey,
        text: prep.text,
        sender_id: prep.sender_id,
        client_id: prep.client_id,
        config: prep.config || {},
        reply_text: welcomeMessage,
        matched: true,
        is_welcome: true,
        is_closing: false,
        next_step: null,
        current_step: null,
        conversation_status: "active",
        conversation_id: prep.conversation_id
      }
    }
  ];
}

// 2) Auto replies only
let match = null;

for (const r of replies) {
  const trigger = String(r.trigger_text || "").toLowerCase().trim();
  if (trigger && text.includes(trigger)) {
    match = r.reply_text;
    break;
  }
}

return [
  {
    json: {
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      client_id: integration.client_id,
      config: integration.config || {},
      reply_text: match,
      matched: !!match,
      is_welcome: false,
      is_closing: false,
      next_step: null,
      current_step: prep.current_step || null,
      conversation_status: prep.conversation_status || "active",
      conversation_id: prep.conversation_id
    }
  }
];

const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;

let aiRaw =
  $json.choices?.[0]?.message?.content ||
  '{"reply":"عذرًا، لم أتمكن من إنشاء رد الآن.","intent":"unknown"}';

let parsed;

try {
  parsed = JSON.parse(aiRaw);
} catch (e) {
  parsed = {
    reply: aiRaw,
    intent: "unknown"
  };
}

const intent = parsed.intent || "unknown";

let replyText = parsed.reply || "عذرًا، لم أتمكن من إنشاء رد الآن.";

// لا نخلي AI يطلب الاسم والرقم. normalize_reply هو المسؤول.
if (intent === "order") {
  replyText = "ممتاز 👌 خلينا نبدأ الطلب.";
}

if (intent === "human_request") {
  replyText = "تمام، رح أحوّل طلبك للفريق المختص.";
}

return [
  {
    json: {
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      client_id: integration.client_id,
      config: integration.config || {},
      reply: replyText,
      intent: intent
    }
  }
];

const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;

const stateItems = $items("get_conversation_state", 0, 0) || [];
const state = stateItems.length > 0 ? stateItems[0].json : null;

const prep = $items("prepare_conversation", 0, 0)[0].json;
const text = (prep.text || "").trim();
const currentStep = prep.current_step || state?.current_step || null;
const conversationStatus = prep.conversation_status || state?.conversation_status || null;

function normalizeDigits(str) {
  return String(str || "")
    .replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d))
    .replace(/[۰-۹]/g, d => "۰۱۲۳۴۵۶۷۸۹".indexOf(d));
}

const normalizedText = normalizeDigits(text);

const hasPhoneLikeText = /\+?\d[\d\s-]{7,}/.test(normalizedText);
const hasOnlyNameLikeText = /^[\p{L}\s]{2,}$/u.test(text);

// 1) إذا كنا بمرحلة انتظار بيانات التواصل
if (currentStep === "waiting_for_contact") {
  return [
    {
      json: {
        platform: base.platform,
        channelKey: base.channelKey,
        text: base.text,
        sender_id: base.sender_id,
        client_id: integration.client_id,
        config: integration.config || {},
        intent: "handle_contact",
        message_action: "handle_contact",
        reply_text: null
      }
    }
  ];
}

// 2) إذا تم التقاط lead مسبقًا، وأرسل المستخدم اسم/رقم إضافي
if (conversationStatus === "lead_captured" && (hasPhoneLikeText || hasOnlyNameLikeText)) {
  return [
    {
      json: {
        platform: base.platform,
        channelKey: base.channelKey,
        text: base.text,
        sender_id: base.sender_id,
        client_id: integration.client_id,
        config: integration.config || {},
        intent: "ignore_extra_contact",
        message_action: "ignore_extra_contact",
        reply_text: "تم استلام بياناتك مسبقاً ✅"
      }
    }
  ];
}

// 3) كلمات إنهاء المحادثة
const endWords = [
  "شكرا",
  "شكراً",
  "يسلمو",
  "يعطيك العافية",
  "تمام",
  "خلص",
  "خلص شكرا",
  "اوك شكرا",
  "ممتاز شكرا"
];

const isEndConversation = endWords.some(word => text.includes(word));

if (isEndConversation) {
  return [
    {
      json: {
        platform: base.platform,
        channelKey: base.channelKey,
        text: base.text,
        sender_id: base.sender_id,
        client_id: integration.client_id,
        config: integration.config || {},
        intent: "closing",
        message_action: "end_conversation",
        reply_text: "أهلاً وسهلاً 🙏 إذا احتجت أي شيء أنا موجود."
      }
    }
  ];
}

// 4) الوضع الطبيعي
return [
  {
    json: {
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      client_id: integration.client_id,
      config: integration.config || {},
      intent: null,
      message_action: "continue",
      reply_text: ""
    }
  }
];

const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;

// Supabase RPC may arrive from the HTTP Request node either as
// a returned object or as a one-row array depending on n8n handling.
const resolverItem = $items("resolve_conversation_v2", 0, 0)[0]?.json;

const resolver = Array.isArray(resolverItem)
  ? resolverItem[0]
  : resolverItem;

if (!resolver) {
  throw new Error("Conversation Resolver returned no result");
}

if (!resolver.conversation_id) {
  throw new Error("Conversation Resolver returned no conversation_id");
}

const quickPayload = base.quick_reply_payload || null;

// Welcome is deliberately based on a NEW CHANNEL/ACCOUNT IDENTITY,
// NOT on whether a new conversation/session was created.
const shouldSendWelcome = resolver.is_new_channel_identity === true;

return [
  {
    json: {
      // Channel / sender
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      quick_reply_payload: quickPayload,

      // Client / integration
      client_id: integration.client_id,
      config: integration.config || {},

      // Conversation Model V2
      contact_id: resolver.contact_id,
      channel_identity_id: resolver.channel_identity_id,
      conversation_id: resolver.conversation_id,

      conversation_status: resolver.conversation_status || "active",
      current_step: resolver.current_step || null,

      // Resolver metadata
      resolution: resolver.resolution || null,
      resolver_event_type: resolver.event_type || null,

      is_new_contact: resolver.is_new_contact === true,
      is_new_channel_identity:
        resolver.is_new_channel_identity === true,
      is_new_conversation:
        resolver.is_new_conversation === true,

      // Welcome is independent from new-session creation.
      should_send_welcome: shouldSendWelcome,

      welcome_message:
        integration.welcome_message ||
        integration.client?.welcome_message ||
        integration.clients?.welcome_message ||
        null,
    },
  },
];

const prep = $items("prepare_conversation", 0, 0)[0].json;
const norm = $json;

// أهم سطر 👇
const config = norm.config || prep.config || {};

return [
  {
    json: {
      ...norm,
      config: config, // 👈 هذا الحل
      client_id: prep.client_id,
      sender_id: prep.sender_id,
      platform: prep.platform,
      conversation_id: prep.conversation_id,
      conversation_status: norm.conversation_status || "active",
      current_step: norm.current_step || null,
      reply_from: prep.reply_from || norm.reply_from,

    from_norm: norm.reply_from,
    from_prep: prep.reply_from,
    selected: prep.reply_from || norm.reply_from
    }
  }
];


