const base = $items("Code in JavaScript1", 0, 0)[0].json;
const integration = $items("client_feature", 0, 0)[0].json;
const prep = $items("prepare_conversation", 0, 0)[0].json;
const clients = integration.clients || integration.client || {};

let decision = null;
try {
  decision = $node["message_decision"].json;
} catch (e) {
  decision = null;
}

const conversationId = prep.conversation_id;
const currentStep = prep.current_step || null;
const currentStatus = prep.conversation_status || "active";
const intent = $json.intent || decision?.intent || null;
const quickPayload = base.quick_reply_payload || null;

const hasContactAlready =
  currentStatus === "lead_captured" ||
  currentStep === "contact_captured";

function normalizeDigits(str) {
  return String(str || "")
    .replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d))
    .replace(/[۰-۹]/g, d => "۰۱۲۳۴۵۶۷۸۹".indexOf(d));
}

function aiReplyAsksForContact(reply) {
  const r = String(reply || "").toLowerCase();
  return (
    r.includes("اسمك") ||
    r.includes("رقمك") ||
    r.includes("رقم الهاتف") ||
    r.includes("للتواصل") ||
    r.includes("phone") ||
    r.includes("name")
  );
}

function safeAiReply(fallback) {
  const aiReply = $json.reply || decision?.reply || "";
  if (!aiReply || aiReplyAsksForContact(aiReply)) return fallback;
  return aiReply;
}

function buildReply({
  reply,
  next_step = null,
  current_step = currentStep,
  conversation_status = currentStatus,
  quick_replies = null,
  lead_name = null,
  lead_phone = null,
  reply_source = "system",
}) {
  return [{
    json: {
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      client_id: integration.client_id,
      config: integration.config || {},
      reply,
      next_step,
      current_step,
      conversation_status,
      conversation_id: conversationId,
      quick_replies,
      lead_name,
      lead_phone,
      reply_source,
    }
  }];
}

// متابعة المحادثة السابقة
if (quickPayload === "CONTINUE_PREVIOUS") {
  return buildReply({
    reply: "تمام 👍 كمل رسالتك",
    current_step: "contact_captured",
    conversation_status: "active",
    reply_source: "quick_reply",
  });
}

// بدء محادثة جديدة
if (quickPayload === "START_NEW") {
  return buildReply({
    reply: prep.welcome_message || "مرحباً 👋 كيف يمكنني مساعدتك؟",
    current_step: null,
    conversation_status: "active",
    reply_source: "quick_reply",
  });
}

// سؤال إعادة فتح محادثة مغلقة حديثاً
if (currentStep === "reopen_confirm") {
  return buildReply({
    reply: "هل تريد متابعة المحادثة السابقة أم بدء محادثة جديدة؟",
    current_step: "reopen_confirm",
    conversation_status: "active",
    quick_replies: [
      { content_type: "text", title: "متابعة السابقة", payload: "CONTINUE_PREVIOUS" },
      { content_type: "text", title: "محادثة جديدة", payload: "START_NEW" }
    ],
    reply_source: "system",
  });
}

if (quickPayload === "CLOSE_CONVERSATION") {
  return buildReply({
    reply: "سعدنا بخدمتك 🙏 في أي وقت تحتاجنا نحن جاهزون",
    current_step: "done",
    conversation_status: "closed",
    reply_source: "quick_reply",
  });
}

if (quickPayload === "CONTINUE_CONVERSATION") {
  return buildReply({
    reply: "تمام 👍 كمل رسالتك",
    current_step: "contact_captured",
    conversation_status: currentStatus,
    reply_source: "quick_reply",
  });
}

const textLower = String(base.text || "").toLowerCase().trim();
const isThankYou =
  textLower.includes("شكرا") ||
  textLower.includes("شكراً") ||
  textLower.includes("يسلمو") ||
  textLower.includes("يعطيك العافية");

if (
  ["waiting_human", "lead_captured"].includes(currentStatus) &&
  currentStep === "contact_captured" &&
  isThankYou
) {
  return buildReply({
    reply: "هل تمت مساعدتك من طرفنا؟ 🙏",
    current_step: "closing_confirm",
    conversation_status: currentStatus,
    quick_replies: [
      { content_type: "text", title: "نعم", payload: "CLOSE_CONVERSATION" },
      { content_type: "text", title: "كمل المحادثة", payload: "CONTINUE_CONVERSATION" }
    ],
    reply_source: "system",
  });
}

if (currentStep === "waiting_for_contact") {
  const text = (base.text || "").trim();
  const normalizedText = normalizeDigits(text);
  const phoneMatch = normalizedText.match(/\+?\d[\d\s-]{7,}/);
  const phone = phoneMatch ? phoneMatch[0].replace(/[\s-]/g, "") : null;

  const leadName = normalizedText
    .replace(/\+?\d[\d\s-]{7,}/g, "")
    .replace(/[-+]/g, "")
    .trim();

  const isHumanFlow = currentStatus === "waiting_human";
  const keepStatus = isHumanFlow ? "waiting_human" : "active";

  if (!leadName && !phone) {
    return buildReply({
      reply: "يرجى إرسال الاسم ورقم الهاتف للتواصل 🙏",
      next_step: "waiting_for_contact",
      current_step: "waiting_for_contact",
      conversation_status: keepStatus,
      reply_source: "system",
    });
  }

  if (leadName && !phone) {
    return buildReply({
      reply: "الرقم غير صحيح ❌ يرجى إرسال رقم هاتف صحيح",
      next_step: "waiting_for_contact",
      current_step: "waiting_for_contact",
      conversation_status: keepStatus,
      lead_name: leadName,
      reply_source: "system",
    });
  }

  if (!leadName && phone) {
    return buildReply({
      reply: "يرجى إرسال الاسم أيضًا 🙏",
      next_step: "waiting_for_contact",
      current_step: "waiting_for_contact",
      conversation_status: keepStatus,
      lead_phone: phone,
      reply_source: "system",
    });
  }

  return buildReply({
    reply: isHumanFlow
      ? "تم استلام بياناتك ✅ سيتم التواصل معك قريباً"
      : "تم استلام بياناتك ✅ سيتم المتابعة معك قريباً",
    current_step: "contact_captured",
    conversation_status: isHumanFlow ? "waiting_human" : "lead_captured",
    lead_name: leadName,
    lead_phone: phone,
    reply_source: "system",
  });
}

if (intent === "human_request") {
  if (hasContactAlready) {
    return buildReply({
      reply: "تمام، رح أحوّل طلبك للفريق المختص وبتواصلوا معك بأقرب فرصة 🙏",
      current_step: "contact_captured",
      conversation_status: "waiting_human",
      reply_source: "ai",
    });
  }

  return buildReply({
    reply: "تمام، رح أحوّل طلبك للفريق المختص وبتواصلوا معك بأقرب فرصة 🙏\nممكن تترك اسمك ورقمك عشان يسهل التواصل معك؟",
    next_step: "waiting_for_contact",
    current_step: "waiting_for_contact",
    conversation_status: "waiting_human",
    reply_source: "ai",
  });
}

if (intent === "order") {
  if (hasContactAlready) {
    return buildReply({
      reply: "تمام، تم استلام طلبك ✅ سيتم المتابعة معك قريباً",
      current_step: "contact_captured",
      conversation_status: currentStatus === "waiting_human" ? "waiting_human" : "lead_captured",
      reply_source: "ai",
    });
  }

  return buildReply({
    reply: "ممتاز 👌 خلينا نبدأ الطلب 🙏 ممكن تبعتلي اسمك ورقمك للتواصل؟",
    next_step: "waiting_for_contact",
    current_step: "waiting_for_contact",
    conversation_status: "active",
    reply_source: "ai",
  });
}

let replyText = safeAiReply(
  clients.default_reply ||
  integration.default_reply ||
  "شكراً لتواصلك معنا 🙏 سيتم الرد عليك بأقرب وقت ممكن"
);

return buildReply({
  reply: replyText,
  current_step: currentStep,
  conversation_status: currentStatus,
  reply_source: $json.reply ? "ai" : "system",
});

