    json: {
      platform: base.platform,
      channelKey: base.channelKey,
      text: base.text,
      sender_id: base.sender_id,
      client_id: integration.client_id,
      config: integration.config || {},
      reply: defaultReply,
      next_step: null,
      current_step: null,
      conversation_status: "active",
      conversation_id: prep.conversation_id,
      reply_source: "system"
    }
  }
];





