(() => {
  const state = $node["state_payload"].json || {};
  const prep = $node["prepare_conversation"].json || {};

  const status =
    state.conversation_status === "waiting_human"
      ? "waiting_human"
      : state.conversation_status === "closed"
        ? "closed"
        : "active";

  const payload = {
    conversation_status: status,
    current_step: state.current_step || null,
    last_message_at: $now,
    closed_at: status === "closed" ? $now : null
  };

  // Same-day return reopens the SAME conversation,
  // but it must not keep the previous human assignment.
  if (prep.resolution === "same_day_return") {
    payload.assigned_user_id = null;
    payload.assigned_at = null;
    payload.system_assigned_user_id = null;
    payload.system_assigned_at = null;
  }

  return payload;
})()
}}

